const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate location of the Alisal Fire in Santa Barbara County, California
  const alisalFireLocation = ee.Geometry.Point([-120.08, 34.45]); // Central point of the fire

  const preFireStartDate = '2021-09-25';
  const preFireEndDate = '2021-10-10'; // Before the fire started (Oct 11)
  const postFireStartDate = '2021-10-14'; // After the peak fire activity (Oct 13)
  const postFireEndDate = '2021-10-29';

  const ACRES_TO_SQ_METERS = 4046.86;
  const thresholdAcres = 10000;
  const thresholdSqMeters = thresholdAcres * ACRES_TO_SQ_METERS; // 10,000 acres in square meters

  // Sentinel-2 Cloud Masking Function
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
      qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to SR units
  }

  // NBR calculation function
  function calculateNBR(image) {
    // For Sentinel-2, NIR is B8, SWIR2 is B12
    return image.normalizedDifference(['B8', 'B12']).rename('NBR');
  }

  // 2. Data Acquisition & Check
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  // Pre-fire images
  const preFireCollection = s2
    .filterBounds(alisalFireLocation)
    .filterDate(preFireStartDate, preFireEndDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .map(calculateNBR);

  // Post-fire images
  const postFireCollection = s2
    .filterBounds(alisalFireLocation)
    .filterDate(postFireStartDate, postFireEndDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .map(calculateNBR);

  const preFireSize = await preFireCollection.size().getInfo();
  const postFireSize = await postFireCollection.size().getInfo();

  console.log(`Pre-fire images found: ${preFireSize}`);
  console.log(`Post-fire images found: ${postFireSize}`);

  if (preFireSize === 0 || postFireSize === 0) {
    console.log("Not enough images found for pre-fire or post-fire analysis.");
    console.log("C1");
    return;
  }

  // Select the least cloudy image for each period
  const preFireImage = preFireCollection.median();
  const postFireImage = postFireCollection.median();

  // Calculate dNBR (difference in NBR)
  const dNBR = preFireImage.subtract(postFireImage).rename('dNBR');

  // Define a region of interest around the fire for calculation
  // Create a 50km buffer around the point to ensure we capture the full fire
  const analysisRegion = alisalFireLocation.buffer(50000);

  // Check for valid pixels in dNBR image within the analysis region
  const dNBRPixelCount = await dNBR.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: analysisRegion,
    scale: 30, // Using 30m scale for initial pixel count for S2 data
    maxPixels: 1e9
  }).get('dNBR').getInfo();

  if (dNBRPixelCount === 0 || dNBRPixelCount === null) {
    console.log("No valid pixels after cloud masking and dNBR calculation.");
    console.log("C2");
    return;
  }

  // 3. Burned Area Delineation (dNBR thresholding)
  // Common dNBR thresholds for burn severity:
  // High severity: dNBR > 660 (scaled by 1000 for SR data) -> 0.66
  // Moderate severity: dNBR between 270 and 660 -> 0.27 to 0.66
  // Low severity: dNBR between 100 and 270 -> 0.1 to 0.27
  // Let's use a threshold for significant change, e.g., dNBR > 0.1 (low severity and higher)
  const burnedArea = dNBR.gte(0.1).updateMask(dNBR.gte(0.1)); // Mask non-burned areas

  // Calculate the area of the burned pixels
  // Use a smaller scale (e.g., 10m for Sentinel-2) for more accurate area calculation, but it can be slow
  // For a large area, 30m or 100m might be more practical. Let's use 30m, which is S2's resolution for some bands.
  const stats = await burnedArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: analysisRegion,
    scale: 30, // Sentinel-2 pixel resolution
    maxPixels: 1e9
  });

  const totalBurnedPixels = stats.get('dNBR').getInfo();

  if (totalBurnedPixels === null) {
    console.log("Burned area calculation failed (returned null).");
    console.log("C3");
    return;
  }

  const totalBurnedAreaSqMeters = totalBurnedPixels * (30 * 30); // Area of one pixel is 30m * 30m
  const totalBurnedAreaAcres = totalBurnedAreaSqMeters / ACRES_TO_SQ_METERS;

  console.log(`Calculated Burned Area (sq meters): ${totalBurnedAreaSqMeters.toFixed(2)}`);
  console.log(`Calculated Burned Area (acres): ${totalBurnedAreaAcres.toFixed(2)}`);
  console.log(`Threshold (acres): ${thresholdAcres}`);

  // 5. Validation & Final Answer
  if (totalBurnedAreaAcres === null || isNaN(totalBurnedAreaAcres)) {
    console.log("C3"); // Calculation failed
  } else if (totalBurnedAreaAcres < thresholdAcres) {
    console.log("A"); // Yes, it covered less than 10,000 acres
  } else {
    console.log("B"); // No, it covered 10,000 acres or more
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
